// Build deterministic notification task and event key
const items = $input.all();
const tasks = [];

for (const item of items) {
  const data = item.json;
  const apptId = data.id || data.appointmentId;
  if (!apptId) continue;

  const status = (data.status || 'pending').toLowerCase();
  const patientId = data.patientId || '';
  const doctorId = data.doctorId || '';
  const doctorName = data.doctorName || 'Doctor';
  const patientName = data.patientName || 'Patient';

  // Determine timestamp for deterministic versioning
  const updatedSeconds = (data.updatedAt && data.updatedAt._seconds) 
    ? data.updatedAt._seconds 
    : ((data.requestedAt && data.requestedAt._seconds) ? data.requestedAt._seconds : 'init');

  // Deterministic Idempotency Key: appointmentId + status + timestamp
  const eventKey = `${apptId}_${status}_${updatedSeconds}`;

  let recipientUid = '';
  let recipientRole = '';
  let senderUid = '';
  let title = '';
  let message = '';
  let notifType = 'appointment';

  if (status === 'pending') {
    // Doctor receives new appointment request
    recipientUid = doctorId;
    recipientRole = 'doctor';
    senderUid = patientId;
    title = 'New Appointment Request';
    message = `New appointment request from ${patientName}`;
    notifType = 'appointment_request';
  } else if (status === 'approved') {
    // Patient receives approval
    recipientUid = patientId;
    recipientRole = 'patient';
    senderUid = doctorId;
    title = 'Appointment Approved';
    message = `Your appointment with Dr. ${doctorName} has been approved.`;
    notifType = 'appointment_approved';
  } else if (status === 'rejected') {
    // Patient receives rejection
    recipientUid = patientId;
    recipientRole = 'patient';
    senderUid = doctorId;
    title = 'Appointment Rejected';
    message = `Your appointment request with Dr. ${doctorName} was rejected.`;
    notifType = 'appointment_rejected';
  } else if (status === 'cancelled') {
    // Both patient and doctor should know, default to doctor if patient cancelled
    recipientUid = doctorId;
    recipientRole = 'doctor';
    senderUid = patientId;
    title = 'Appointment Cancelled';
    message = `${patientName} cancelled their scheduled appointment.`;
    notifType = 'appointment_cancelled';
  } else if (status === 'completed') {
    recipientUid = patientId;
    recipientRole = 'patient';
    senderUid = doctorId;
    title = 'Appointment Completed';
    message = `Your consultation with Dr. ${doctorName} is completed.`;
    notifType = 'appointment_completed';
  } else if (status === 'missed') {
    recipientUid = patientId;
    recipientRole = 'patient';
    senderUid = doctorId;
    title = 'Appointment Missed';
    message = `Your scheduled appointment with Dr. ${doctorName} was missed. Please reschedule.`;
    notifType = 'appointment_missed';
  }

  if (recipientUid) {
    tasks.push({
      json: {
        eventKey,
        appointmentId: apptId,
        status,
        recipientUid,
        recipientRole,
        senderUid,
        title,
        message,
        notifType,
        doctorName,
        patientName,
        dateTime: data.dateTime,
        notes: data.notes || ''
      }
    });
  }
}

return tasks;

